// In-app Help: one "how to" article per activity in WareCore.
//
// This list is the single source of truth for both the Help screens
// (/help, /help/[slug]) and the user-guide PowerPoint (generated by
// scripts/help/build-user-guide.mjs), so the two never drift apart.
// Screenshots live in public/help/screens/<slug>.jpg and are produced by
// scripts/help/capture-screenshots.mjs against a demo database.

export type HelpCategory =
  | 'Getting Started'
  | 'Master Data'
  | 'Purchases'
  | 'Stock & Transfers'
  | 'Job Work'
  | 'Sales'
  | 'Accounts'
  | 'Reports'
  | 'Data Integrity'
  | 'Administration'

export const HELP_CATEGORIES: { name: HelpCategory; blurb: string }[] = [
  { name: 'Getting Started', blurb: 'Signing in, finding your way around and getting help' },
  { name: 'Master Data', blurb: 'Companies, warehouses, parties, materials, items, tax, users and roles' },
  { name: 'Purchases', blurb: 'Entering, importing, editing and cancelling purchase bills' },
  { name: 'Stock & Transfers', blurb: 'Current stock, stock movements and transfers between locations' },
  { name: 'Job Work', blurb: 'Sending material to vendors, receiving it back and moving it between vendors' },
  { name: 'Sales', blurb: 'Sale entries, selling from a vendor, cancellations and customer returns' },
  { name: 'Accounts', blurb: 'Customer receipts and supplier payments' },
  { name: 'Reports', blurb: 'Stock, purchase, sales, job work and traceability reports' },
  { name: 'Data Integrity', blurb: 'Checking the stock ledger and fixing exceptions' },
  { name: 'Administration', blurb: 'Backups, restore and service information' },
]

export type HelpArticle = {
  slug: string
  title: string
  category: HelpCategory
  /** One sentence: what this activity is for. */
  summary: string
  /** The screen where the activity is done (the "Open this screen" button). */
  path: string
  pathLabel: string
  /** Numbered steps. */
  steps: string[]
  tips?: string[]
  /** Extra words people might search for. */
  keywords?: string[]
  related?: string[]
  /** Screens this article is the help for, e.g. '/bills/[id]/edit'. Used by the header Help button. */
  screens?: string[]
  /** False when there is no screenshot for this article. */
  screenshot?: boolean
}

