export const HELP_BY_SLUG: Record<string, HelpArticle> = Object.fromEntries(HELP_ARTICLES.map((a) => [a.slug, a]))

export function helpScreenshotSrc(a: HelpArticle): string | null {
  return a.screenshot === false ? null : `/help/screens/${a.slug}.jpg`
}

// '/bills/[id]/edit' → /^\/bills\/[^/]+\/edit$/
function screenPattern(screen: string): RegExp {
  const body = screen.split('/').map((seg) => (/^\[.+\]$/.test(seg) ? '[^/]+' : seg.replace(/[.*+?^${}()|\\]/g, '\\$&'))).join('/')
  return new RegExp(`^${body}/?$`)
}

/** Articles that are the help for the screen at `pathname` (most specific first). */
export function helpForPath(pathname: string): HelpArticle[] {
  const clean = pathname.split('?')[0]
  const hits: { a: HelpArticle; score: number }[] = []
  for (const a of HELP_ARTICLES) {
    const match = (a.screens ?? []).filter((s) => screenPattern(s).test(clean))
    if (match.length) hits.push({ a, score: Math.max(...match.map((s) => s.length + (s.includes('[') ? 0 : 1))) })
  }
  if (!hits.length) {
    // No exact screen: fall back to the module (first path segment).
    const top = '/' + (clean.split('/')[1] ?? '')
    for (const a of HELP_ARTICLES) if ((a.screens ?? []).some((s) => s === top)) hits.push({ a, score: 0 })
  }
  return hits.sort((x, y) => y.score - x.score).map((h) => h.a)
}

const normalise = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()

/** Ranked search over titles, summaries, keywords, steps and tips. Every word must appear. */
export function searchHelp(query: string): HelpArticle[] {
  const words = normalise(query).split(' ').filter(Boolean)
  if (!words.length) return []
  const scored: { a: HelpArticle; score: number }[] = []
  for (const a of HELP_ARTICLES) {
    const fields: [string, number][] = [
      [normalise(a.title), 6],
      [normalise((a.keywords ?? []).join(' ')), 4],
      [normalise(a.summary + ' ' + a.category + ' ' + a.pathLabel), 2],
      [normalise(a.steps.join(' ') + ' ' + (a.tips ?? []).join(' ')), 1],
    ]
    let score = 0
    let all = true
    for (const w of words) {
      let best = 0
      let hits = 0
      for (const [text, weight] of fields) {
        if (text.includes(w)) best = Math.max(best, weight + (new RegExp(`\\b${w}\\b`).test(text) ? 1 : 0))
        hits += text.split(w).length - 1
      }
      if (!best) { all = false; break }
      // Strongest field decides; how often the word comes up breaks ties.
      score += best + Math.min(hits, 40) * 0.05
    }
    // Undo-type guides (cancel, reverse, archives) rank after the main activity they undo.
    if (all) scored.push({ a, score: score - (/^(cancel|reverse)-|cancellations$/.test(a.slug) ? 1 : 0) })
  }
  return scored.sort((x, y) => y.score - x.score || x.a.title.localeCompare(y.a.title)).map((s) => s.a)
}

/** Every article title plus every keyword-style index term, A–Z. */
export function helpIndex(): { term: string; slug: string }[] {
  return [...HELP_ARTICLES]
    .map((a) => ({ term: a.title, slug: a.slug }))
    .sort((x, y) => x.term.localeCompare(y.term))
}
